def _data_dir():
    """可写数据目录：Android 用 user_data_dir，Windows 用脚本同目录"""
    if _IS_ANDROID:
        try: return App.get_running_app().user_data_dir
        except: return os.path.join(os.path.expanduser("~"), ".jpstudy")
    return os.path.dirname(__file__)

def load_data():
    """加载进度JSON"""
    p=os.path.join(_data_dir(),"jpstudy_progress.json")
    default={"current_vocab":"第1天","custom_words":[],"mastered":[],"errors":[],"quiz_active":False,"quiz_unit":"","quiz_all_words":[],"quiz_start_index":0}
    if not os.path.exists(p): return default
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except: return default

def save_data(d):
    """保存进度JSON"""
    p=os.path.join(_data_dir(),"jpstudy_progress.json")
    with open(p,'w',encoding='utf-8') as f: json.dump(d,f,ensure_ascii=False,indent=2)

# ==================== 工具组件 ====================
class RoundedButton(Button):
    def __init__(self,bg=PRIMARY,fc=WHITE,**kw):
        super().__init__(**kw)
        self.bg,self.fc = bg,fc
        self.color=fc; self.background_normal=''; self.background_color=(0,0,0,0)
        self.size_hint_y=None; self.height=dp(48)
        self.bind(size=self._r,pos=self._r)
    def _r(self,*a):
        self.canvas.before.clear()
        with self.canvas.before: Color(*self.bg); RoundedRectangle(pos=self.pos,size=self.size,radius=[12])

class Badge(Label):
    def __init__(self,bg=PRIMARY_LIGHT,fc=PRIMARY,**kw):
        super().__init__(**kw)
        self.bg,self.fc=bg,fc
        self.color=fc; self.font_size=sp(12)
        self.size_hint=(None,None); self.padding=(dp(10),dp(3))
        self.bind(size=self._u,texture_size=self._s)
    def _s(self,*a):
        self.width=self.texture_size[0]+dp(20)
        self.height=self.texture_size[1]+dp(6)
        self._u()
    def _u(self,*a):
        self.canvas.before.clear()
        with self.canvas.before: Color(*self.bg); RoundedRectangle(pos=self.pos,size=self.size,radius=[10])

# ==================== 主应用 ====================
class JpApp(App):
    def __init__(self,**kw):
        super().__init__(**kw)
        d=load_data()
        self.current_vocab=d["current_vocab"]
        self.custom_words=d["custom_words"]
        self.mastered=d["mastered"]
        self.errors=d["errors"]
        self.quiz_cn_words=[]; self.quiz_jp_words=[]
        self.quiz_idx=0; self.quiz_correct=0
        self.quiz_streak=0; self.quiz_max_streak=0; self.quiz_total=0
        # 会话式刷题状态（从存储恢复）
        self.quiz_active=d.get("quiz_active",False)
        self.quiz_unit=d.get("quiz_unit",None)
        self.quiz_all_words=d.get("quiz_all_words",[])
        self.quiz_start_index=d.get("quiz_start_index",0)
        # 如果池空了但标记还在，说明上一轮测完了，重置
        if self.quiz_active and not self.quiz_all_words:
            self.quiz_active=False

    def build(self):
        Window.clearcolor=BG
        if not _IS_ANDROID:
            Window.size=(400,700)
            # Windows IME 唤醒
            try:
                import ctypes
                imm32=ctypes.windll.imm32
                hwnd=ctypes.windll.user32.GetActiveWindow()
                hIMC=imm32.ImmGetContext(hwnd)
                if hIMC:
                    imm32.ImmSetOpenStatus(hIMC,1)
                    imm32.ImmReleaseContext(hwnd,hIMC)
            except: pass
        else:
            Window.bind(on_keyboard=self._android_back)
        self.root = MainLayout(app=self)
        return self.root

    def _android_back(self,window,key,*a):
        if key!=27: return False
        ml=self.root
        if ml.tab_idx==2 and ml.error_unit is not None:
            ml._close_error_unit()
        elif ml.vocab_unit is not None:
            ml._close_vocab_unit()
        elif ml.tab_idx!=0:
            ml.switch_tab(0)
        elif ml.quiz_active:
            self.quiz_active=False
            ml.switch_tab(0)
        else:
            return False  # 退出 app
        return True

    def get_words(self):
        return self.custom_words if self.current_vocab=="[自定义]" else VOCAB.get(self.current_vocab,[])

    def _save(self):
        d={"current_vocab":self.current_vocab,"custom_words":self.custom_words,
           "mastered":self.mastered,"errors":self.errors,
           "quiz_active":self.quiz_active,"quiz_unit":self.quiz_unit,
           "quiz_all_words":self.quiz_all_words,"quiz_start_index":self.quiz_start_index}
        save_data(d)

    def start_quiz(self,unit=None):
        """从单元目录开始一轮新的刷题会话"""
        if unit is None: unit=self.current_vocab
        if unit=="[自定义]": words=list(self.custom_words)
        else: words=list(VOCAB.get(unit,[]))
        if not words: self.toast("无单词"); return
        self.quiz_active=True
        self.quiz_unit=unit
        self.root.current_quiz_unit=unit
        self.quiz_all_words=list(words)
        random.shuffle(self.quiz_all_words)
        self.quiz_start_index=0
        self._next_round()

    def _next_round(self):
        """从池中取下一组10词"""
        remain=len(self.quiz_all_words)-self.quiz_start_index
        if remain<=0:
            self.quiz_active=False
            self.toast("本轮所有单词已测完！")
            return
        take=min(10,remain)
        round_words=self.quiz_all_words[self.quiz_start_index:self.quiz_start_index+take]
        self.quiz_start_index+=take
        random.shuffle(round_words)
        half=max(1,take//2)
        self.quiz_cn_words=round_words[:half]
        self.quiz_jp_words=round_words[half:]
        self.quiz_total=take
        self.quiz_idx=0; self.quiz_correct=0; self.quiz_streak=0; self.quiz_max_streak=0
        self.quiz_mode='cn'
        if self.quiz_cn_words: self.root.show_quiz('cn')
        elif self.quiz_jp_words: self.root.show_quiz('jp')

    def start_error_review(self):
        uniq=[]; seen=set()
        for e in self.errors:
            if e["kana"] not in seen: seen.add(e["kana"]); uniq.append(e)
        if not uniq: self.toast("没有错题"); return
        self.quiz_active=False  # 错题重练独立于会话
        self.root.current_quiz_unit="全部错题"
        self.quiz_correct=0; self.quiz_streak=0; self.quiz_max_streak=0
        s=list(uniq); random.shuffle(s)
        cnt=min(10,len(s)); half=max(1,cnt//2)
        self.quiz_cn_words=s[:half]; self.quiz_jp_words=s[half:cnt]
        self.quiz_total=len(self.quiz_cn_words)+len(self.quiz_jp_words)
        self.quiz_idx=0
        if self.quiz_cn_words: self.root.show_quiz('cn')
        elif self.quiz_jp_words: self.root.show_quiz('jp')

    def show_result(self):
        self.root.show_result()

    def toast(self,msg):
        p=Popup(title='',content=Label(text=msg,color=TEXT,font_size=sp(15)),
                size_hint=(0.7,0.25),background='',background_color=(0,0,0,0),separator_height=0)
        p.open(); Clock.schedule_once(lambda dt:p.dismiss(),1.5)

    def confirm_exit(self):
        self._save(); App.get_running_app().stop()

# ==================== 底部导航 ====================
class BottomNav(BoxLayout):
    def __init__(self,app,**kw):
        super().__init__(**kw)
        self.app=app
        self.size_hint_y=None; self.height=dp(60)
        with self.canvas.before: Color(*WHITE); Rectangle(pos=self.pos,size=self.size)
        self.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                   size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        self.btns=[]
        for icon,label,target in [("[课]","主页",0),("[库]","题库",1),("[错]","错题",2)]:
            # FloatLayout for precise overlay
            fl=FloatLayout()
            # Content centered
            content=BoxLayout(orientation='vertical',spacing=dp(2),
                               size_hint=(None,None),size=(dp(60),dp(40)),
                               pos_hint={'center_x':0.5,'center_y':0.5})
            lbl=Label(text=icon,font_size=sp(20),size_hint_y=None,height=dp(24),color=TEXT_SECONDARY)
            sub=Label(text=label,font_size=sp(10),color=TEXT_SECONDARY,size_hint_y=None,height=dp(14))
            content.add_widget(lbl); content.add_widget(sub)
            fl.add_widget(content)
            # Button overlaid on content only
            btn=Button(size_hint=(None,None),size=(dp(60),dp(40)),
                       pos_hint={'center_x':0.5,'center_y':0.5},
                       background_normal='',background_color=(0.3,0.56,0.85,0.08))
            btn.bind(on_release=lambda x,t=target:self.app.root.switch_tab(t))
            fl.add_widget(btn)
            self.add_widget(fl)
            self.btns.append((lbl,sub,fl))

    def set_active(self,idx):
        for i,(lbl,sub,box) in enumerate(self.btns):
            c=PRIMARY if i==idx else TEXT_SECONDARY
            lbl.color=c; sub.color=c

# ==================== 主布局 ====================
class MainLayout(BoxLayout):
    def __init__(self,app,**kw):
        super().__init__(**kw)
        self.app=app; self.orientation='vertical'
        self.tab_idx=0
        self.error_unit=None
        self.vocab_unit=None
        self.current_quiz_unit=None
        self._build()

    def _build(self):
        # Header
        self.header=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(48),padding=[dp(16),0])
        with self.header.canvas.before: Color(*WHITE); Rectangle(pos=self.header.pos,size=self.header.size)
        self.header.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                          size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        self.title=Label(text="[学] 日语单词",font_size=sp(17),bold=True,color=TEXT,halign='left')
        self.title.bind(size=lambda s,w:setattr(s,'text_size',(s.width,None)))
        self.header.add_widget(self.title)
        self.status_sub=Label(text="",font_size=sp(13),color=TEXT_SECONDARY,halign='right',size_hint_x=0.5)
        self.header.add_widget(self.status_sub)
        self.add_widget(self.header)

        # Content area
        self.content=BoxLayout(orientation='vertical')
        self.add_widget(self.content)

        # Bottom nav
        self.nav=BottomNav(app=self.app)
        self.add_widget(self.nav)

        # Build tab content
        self.tabs=[]
        self._build_home()
        self._build_vocab()
        self._build_error()
        self.switch_tab(0)

    def _clear_content(self):
        self.content.clear_widgets()

    def switch_tab(self,idx):
        self.tab_idx=idx
        self._clear_content()
        scr=ScrollView(bar_width=dp(4))
        c=BoxLayout(orientation='vertical',size_hint_y=None,spacing=dp(0),padding=[dp(16),dp(8),dp(16),dp(16)])
        c.bind(minimum_height=c.setter('height'))
        if idx==0: self._fill_home(c)
        elif idx==1: self._fill_vocab(c)
        else: self._fill_error(c)
        scr.add_widget(c)
        self.content.add_widget(scr)
        self.nav.set_active(idx)
        self._refresh_header()

    def _refresh_header(self):
        known=len(self.app.mastered)
        err=len(set(e["kana"] for e in self.app.errors))
        if self.app.current_vocab:
            t=["[课] "+self.app.current_vocab]
            if known: t.append(str(known)+"词")
            if err: t.append("[错]"+str(err))
            self.status_sub.text=" | ".join(t)
        else:
            self.status_sub.text="未选题库"

    def _get_word_unit(self,word):
        """查找单词属于哪个单元"""
        for uname,words in VOCAB.items():
            for w in words:
                if w["kana"]==word["kana"] and w["kanji"]==word["kanji"]:
                    return uname
        for w in self.app.custom_words:
            if w["kana"]==word["kana"]:
                return "[自定义]"
        return "其他"

    # ---------- 主页 ----------
    def _build_home(self): pass

    def menu_btn(self,icon,label,desc,color,callback):
        box=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(56),spacing=dp(12),padding=[0,dp(8)])
        ic=Label(text=icon,font_size=sp(22),size_hint=(None,1),width=dp(44),color=color)
        with ic.canvas.before: Color(*PRIMARY_LIGHT); RoundedRectangle(pos=ic.pos,size=ic.size,radius=[12])
        ic.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        box.add_widget(ic)
        tb=BoxLayout(orientation='vertical',spacing=dp(2))
        tb.add_widget(Label(text=label,font_size=sp(16),bold=True,color=TEXT,halign='left',size_hint_y=None,height=dp(22)))
        if desc:
            tb.add_widget(Label(text=desc,font_size=sp(12),color=TEXT_SECONDARY,halign='left',size_hint_y=None,height=dp(18)))
        box.add_widget(tb)
        box.add_widget(Label(text=">",font_size=sp(20),color=(0.8,0.82,0.88,1),size_hint=(None,1),width=dp(20)))
        btn=Button(size_hint=(1,1),background_normal='',background_color=(0.3,0.56,0.85,0.08))
        btn.bind(on_release=lambda x:callback())
        box.add_widget(btn)
        return box

    def _fill_home(self,c):
        # Status card
        sc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(6))
        with sc.canvas.before: Color(*WHITE); RoundedRectangle(pos=sc.pos,size=sc.size,radius=[16])
        sc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        bc=BoxLayout(size_hint_y=None,height=dp(26),spacing=dp(6))
        if self.app.current_vocab:
            bc.add_widget(Badge(text="[课] "+self.app.current_vocab))
            bc.add_widget(Badge(text="[OK]"+str(len(self.app.mastered))+"已掌握",bg=(0.94,0.99,0.95,1),fc=(0.09,0.64,0.20,1)))
            n_err=len(set(e["kana"] for e in self.app.errors))
            if n_err: bc.add_widget(Badge(text="[错]"+str(n_err)+"错题",bg=(1,0.95,0.95,1),fc=DANGER))
            sc.add_widget(bc)
            t=len(self.app.get_words()) or 1
            pct=int(len(self.app.mastered)/t*100)
            sc.add_widget(Label(text="进度 "+str(pct)+"%",font_size=sp(13),color=TEXT_SECONDARY,size_hint_y=None,height=dp(20)))
        else:
            bc.add_widget(Badge(text="未选题库",bg=(0.95,0.95,0.95,1),fc=TEXT_SECONDARY))
            sc.add_widget(bc)
        sc.bind(minimum_height=sc.setter('height'))
        c.add_widget(sc)

        # Menu card
        mc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16))
        mc.bind(minimum_height=mc.setter('height'))
        with mc.canvas.before: Color(*WHITE); RoundedRectangle(pos=mc.pos,size=mc.size,radius=[16])
        mc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        active=self.app.quiz_active and self.app.quiz_all_words
        if active:
            icon="[继]"; label="继续刷题"
            remain=len(self.app.quiz_all_words)-self.app.quiz_start_index
            unit=self.app.quiz_unit or ""
            desc=unit+" 还有 "+str(remain)+" 词待测"
            cb=lambda: self._continue_quiz()
        else:
            icon="[题]"; label="开始刷题"
            desc="中译日+日译中 每轮10题"
            cb=lambda: self.switch_tab(1)
        menu_items=[
            (icon,label,desc,PRIMARY,cb),
            ("[库]","更换题库","选择单元或自定义",(0.59,0.22,0.84,1),lambda: self.switch_tab(1)),
            ("[OK]","已掌握单词",str(len(self.app.mastered))+" 词已掌握" if self.app.mastered else "暂无已掌握单词",(0.09,0.64,0.20,1),lambda: self._show_mastered()),
            ("[退]","退出","保存进度并退出",TEXT_SECONDARY,self.app.confirm_exit),
        ]
        for idx,(icon,label,desc,color,cb) in enumerate(menu_items):
            mc.add_widget(self.menu_btn(icon,label,desc,color,cb))
            if idx < len(menu_items)-1:
                s=BoxLayout(size_hint_y=None,height=dp(1))
                with s.canvas.before: Color(*BORDER); Rectangle(pos=s.pos,size=s.size)
                s.bind(pos=lambda x,v:setattr(x.canvas.before.children[-1],'pos',v),
                       size=lambda x,v:setattr(x.canvas.before.children[-1],'size',v))
                mc.add_widget(s)
        c.add_widget(mc)

    # ---------- 题库（目录 + 单词列表）----------
    def _build_vocab(self): pass

    def _fill_vocab(self,c):
        if self.vocab_unit is None:
            self._fill_vocab_dir(c)
        else:
            self._fill_vocab_words(c)

    def _fill_vocab_dir(self,c):
        # 单元目录
        mc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=0)
        mc.bind(minimum_height=mc.setter('height'))
        with mc.canvas.before: Color(*WHITE); RoundedRectangle(pos=mc.pos,size=mc.size,radius=[16])
        mc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        mc.add_widget(Label(text="-- 单元目录 --",font_size=sp(14),bold=True,color=TEXT,
                             size_hint_y=None,height=dp(24),halign='center'))
        for i,(name,words) in enumerate(VOCAB.items(),1):
            if name=="随机复习": continue
            mc.add_widget(self._vocab_item(str(i),name,len(words),lambda n=name:self._open_vocab_unit(n)))
        c.add_widget(mc)

        # 随机复习
        rc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(8))
        rc.bind(minimum_height=rc.setter('height'))
        with rc.canvas.before: Color(*WHITE); RoundedRectangle(pos=rc.pos,size=rc.size,radius=[16])
        rc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        rc.add_widget(Label(text="-- 随机复习 --",font_size=sp(14),bold=True,color=TEXT,
                             size_hint_y=None,height=dp(24),halign='center'))
        rc.add_widget(Label(text="从所有单元随机抽题",font_size=sp(13),color=TEXT_SECONDARY,
                             size_hint_y=None,height=dp(20),halign='center'))
        btn=RoundedButton(text="开始随机复习",bg=PRIMARY)
        btn.bind(on_release=lambda x:self._open_vocab_unit("随机复习"))
        rc.add_widget(btn)
        c.add_widget(rc)

        # 自定义题库
        self._build_custom_section(c)

    def _fill_vocab_words(self,c):
        """显示选中单元的所有单词"""
        unit=self.vocab_unit
        if unit=="[自定义]":
            words=list(self.app.custom_words)
        else:
            words=list(VOCAB.get(unit,[]))

        card=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
        card.bind(minimum_height=card.setter('height'))
        with card.canvas.before: Color(*WHITE); RoundedRectangle(pos=card.pos,size=card.size,radius=[16])
        card.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                  size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))

        # Back button
        back_row=BoxLayout(size_hint_y=None,height=dp(32))
        bk=Button(text="< 返回目录",font_size=sp(14),color=PRIMARY,
                  size_hint=(None,None),size=(dp(100),dp(32)),
                  background_normal='',background_color=(0,0,0,0))
        bk.bind(on_release=lambda x:self._close_vocab_unit())
        back_row.add_widget(bk)
        back_row.add_widget(Widget())
        card.add_widget(back_row)

        # Unit title
        card.add_widget(Label(text="["+unit+"]",font_size=sp(16),bold=True,color=TEXT,
            size_hint_y=None,height=dp(24),halign='left'))
        card.add_widget(Label(text="共 "+str(len(words))+" 词",font_size=sp(13),color=TEXT_SECONDARY,
            size_hint_y=None,height=dp(18),halign='left'))

        if not words:
            card.add_widget(Label(text="无单词数据",font_size=sp(14),color=TEXT_SECONDARY,
                size_hint_y=None,height=dp(30)))
        else:
            for w in words:
                d=w["kanji"]+"("+w["kana"]+")" if w["kanji"] else w["kana"]
                known=any(m["kana"]==w["kana"] for m in self.app.mastered)
                err=any(e["kana"]==w["kana"] for e in self.app.errors)
                mark=""
                if known: mark=" [V]"
                elif err: mark=" [X]"
                card.add_widget(Label(text="  "+d+" -> "+w["cn"]+mark,
                    font_size=sp(14),color=TEXT,size_hint_y=None,height=dp(26)))

        c.add_widget(card)

        # Start quiz button
        btn_row=BoxLayout(size_hint_y=None,height=dp(50))
        btn_row.add_widget(Widget())
        qbtn=RoundedButton(text="开始刷题",bg=PRIMARY,size_hint=(None,None),width=dp(200))
        qbtn.bind(on_release=lambda x:self._start_vocab_quiz(unit))
        btn_row.add_widget(qbtn)
        btn_row.add_widget(Widget())
        c.add_widget(btn_row)

    def _vocab_item(self,num,name,count,cb):
        box=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(44),spacing=dp(12),padding=[0,dp(4)])
        nl=Label(text=num,font_size=sp(14),bold=True,color=PRIMARY,size_hint=(None,1),width=dp(32))
        with nl.canvas.before: Color(*PRIMARY_LIGHT); RoundedRectangle(pos=nl.pos,size=nl.size,radius=[16])
        nl.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        box.add_widget(nl)
        box.add_widget(Label(text=name,font_size=sp(16),color=TEXT,halign='left',size_hint_x=1))
        cl=Label(text=str(count)+"词",font_size=sp(13),color=TEXT_SECONDARY,size_hint=(None,1),width=dp(60))
        with cl.canvas.before: Color(*BORDER); RoundedRectangle(pos=cl.pos,size=cl.size,radius=[10])
        cl.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        box.add_widget(cl)
        box.add_widget(Label(text=">",font_size=sp(18),color=(0.8,0.82,0.88,1),size_hint=(None,1),width=dp(20)))
        btn=Button(size_hint=(1,1),background_normal='',background_color=(0.3,0.56,0.85,0.08))
        btn.bind(on_release=lambda x:cb())
        box.add_widget(btn)
        return box

    def _open_vocab_unit(self,name):
        self.vocab_unit=name
        self.switch_tab(1)

    def _close_vocab_unit(self):
        self.vocab_unit=None
        self.switch_tab(1)

    def _continue_quiz(self):
        """继续中断的刷题会话"""
        if self.app.quiz_cn_words or self.app.quiz_jp_words:
            self.show_quiz(self.app.quiz_mode)
        else:
            self.app._next_round()

    def _start_vocab_quiz(self,name):
        self.app.current_vocab=name
        self.app.mastered=[]
        self.error_unit=None
        self.vocab_unit=None
        self.app._save()
        self._refresh_header()
        self.app.start_quiz(name)

    def _build_custom_section(self,c):
        card=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(8))
        card.bind(minimum_height=card.setter('height'))
        with card.canvas.before: Color(*WHITE); RoundedRectangle(pos=card.pos,size=card.size,radius=[16])
        card.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                  size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        h=BoxLayout(size_hint_y=None,height=dp(36))
        h.add_widget(Label(text="[题] 自定义题库",font_size=sp(15),bold=True,color=TEXT,halign='left'))
        ab=RoundedButton(text="+添加",bg=PRIMARY,size_hint=(None,None),width=dp(80),height=dp(34))
        ab.bind(on_release=lambda x:self._show_add_popup())
        h.add_widget(ab)
        card.add_widget(h)
        self.clist=BoxLayout(orientation='vertical',size_hint_y=None,spacing=0)
        self.clist.bind(minimum_height=self.clist.setter('height'))
        card.add_widget(self.clist)
        self._refresh_custom()
        c.add_widget(card)

    def _refresh_custom(self):
        if not hasattr(self,'clist'): return
        self.clist.clear_widgets()
        if not self.app.custom_words:
            self.clist.add_widget(Label(text="暂无自定义单词",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(36)))
            return
        for i,w in enumerate(self.app.custom_words):
            box=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(36),spacing=dp(8))
            d=w["kanji"] if w["kanji"] else "(外来词)"
            box.add_widget(Label(text=d+"("+w["kana"]+") -> "+w["cn"],font_size=sp(14),color=TEXT,halign='left',size_hint_x=1))
            db=Button(text="x",font_size=sp(14),color=DANGER,size_hint=(None,1),width=dp(32),
                       background_normal='',background_color=(0,0,0,0))
            db.bind(on_release=lambda x,idx=i:self._del_custom(idx))
            box.add_widget(db)
            self.clist.add_widget(box)

    def _del_custom(self,idx):
        if 0<=idx<len(self.app.custom_words):
            self.app.custom_words.pop(idx); self.app._save(); self._refresh_custom()

    def _show_add_popup(self):
        content=BoxLayout(orientation='vertical',spacing=dp(12),padding=dp(20),size_hint_y=None)
        content.bind(minimum_height=content.setter('height'))
        inputs={}
        for label,hint,key in [("日语汉字（留空=外来词）","例：食べる","kanji"),("日语假名 *","例：たべる","kana"),("中文意思 *","例：吃、进食","cn")]:
            b=BoxLayout(orientation='vertical',size_hint_y=None,height=dp(60),spacing=dp(4))
            b.add_widget(Label(text=label,font_size=sp(14),color=TEXT_SECONDARY,halign='left',size_hint_y=None,height=dp(18)))
            ti=TextInput(hint_text=hint,font_size=sp(16),size_hint_y=None,height=dp(36),
                         background_color=WHITE,foreground_color=TEXT,padding=[dp(8),dp(6)])
            b.add_widget(ti); inputs[key]=ti; content.add_widget(b)
        popup=Popup(title="添加单词",content=content,size_hint=(0.85,None),height=dp(340),
                    background='',background_color=(0,0,0,0),separator_height=dp(1))
        br=BoxLayout(size_hint_y=None,height=dp(44),spacing=dp(12))
        def do_add(x):
            kana=inputs["kana"].text.strip()
            cn=inputs["cn"].text.strip()
            if not kana or not cn: self.app.toast("假名和中文必填"); return
            self.app.custom_words.append({"kanji":inputs["kanji"].text.strip(),"kana":kana,"cn":cn})
            self.app._save(); self._refresh_custom(); popup.dismiss()
        br.add_widget(RoundedButton(text="添加",bg=PRIMARY,on_release=do_add))
        br.add_widget(RoundedButton(text="取消",bg=(0.95,0.95,0.95,1),fc=TEXT,on_release=lambda x:popup.dismiss()))
        content.add_widget(br); popup.content=content; popup.open()

    # ---------- 错题 ----------
    def _build_error(self): pass

    # ---- 错题库：目录 + 单元详情 ----
    def _fill_error(self,c):
        err_total=len(set(e["kana"] for e in self.app.errors))

        # Build unit-grouped data
        unit_groups={}
        seen=set()
        repeat={}
        for e in self.app.errors:
            repeat[e["kana"]]=repeat.get(e["kana"],0)+1
        for e in self.app.errors:
            if e["kana"] in seen: continue
            seen.add(e["kana"])
            unit=self._get_word_unit(e)
            if unit not in unit_groups: unit_groups[unit]=[]
            unit_groups[unit].append(e)

        # 错题重练卡片 (always visible)
        rc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(20),spacing=dp(8))
        rc.bind(minimum_height=rc.setter('height'))
        with rc.canvas.before: Color(*WHITE); RoundedRectangle(pos=rc.pos,size=rc.size,radius=[16])
        rc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        rc.add_widget(Label(text="[错]",font_size=sp(40),size_hint_y=None,height=dp(50)))
        rc.add_widget(Label(text="全部错题重练",font_size=sp(17),bold=True,color=TEXT,size_hint_y=None,height=dp(24)))
        rc.add_widget(Label(text="共 "+str(err_total)+" 道错题" if err_total else "暂无错题",
            font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(20)))
        btn_row=BoxLayout(size_hint_y=None,height=dp(50))
        btn_row.add_widget(Widget())
        btn=RoundedButton(text="开始复习",bg=PRIMARY,size_hint=(None,None),width=dp(200))
        btn.bind(on_release=lambda x:self.app.start_error_review())
        btn_row.add_widget(btn)
        btn_row.add_widget(Widget())
        rc.add_widget(btn_row)
        c.add_widget(rc)

        if self.error_unit is None:
            # === 目录视图：显示每个单元的错题数 ===
            dc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
            dc.bind(minimum_height=dc.setter('height'))
            with dc.canvas.before: Color(*WHITE); RoundedRectangle(pos=dc.pos,size=dc.size,radius=[16])
            dc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                    size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
            dc.add_widget(Label(text="错题库目录",font_size=sp(15),bold=True,color=TEXT,
                size_hint_y=None,height=dp(22),halign='left'))
            if err_total==0:
                dc.add_widget(Label(text="[!!] 暂无错题",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(36)))
            else:
                dc.add_widget(Label(text="按单元查看错题",font_size=sp(13),color=TEXT_SECONDARY,size_hint_y=None,height=dp(18),halign='left'))
                for uname in sorted(unit_groups.keys()):
                    cnt=len(unit_groups[uname])
                    item=self._error_dir_item(uname,cnt,lambda u=uname:self._open_error_unit(u))
                    dc.add_widget(item)
            dc.bind(minimum_height=dc.setter('height'))
            c.add_widget(dc)
        else:
            # === 单元详情视图：显示指定单元的错题 ===
            dv=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
            dv.bind(minimum_height=dv.setter('height'))
            with dv.canvas.before: Color(*WHITE); RoundedRectangle(pos=dv.pos,size=dv.size,radius=[16])
            dv.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                    size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
            # Back button
            back_row=BoxLayout(size_hint_y=None,height=dp(32))
            bk=Button(text="< 返回目录",font_size=sp(14),color=PRIMARY,
                      size_hint=(None,None),size=(dp(100),dp(32)),
                      background_normal='',background_color=(0,0,0,0))
            bk.bind(on_release=lambda x:self._close_error_unit())
            back_row.add_widget(bk)
            back_row.add_widget(Widget())
            dv.add_widget(back_row)
            # Unit title
            dv.add_widget(Label(text="["+self.error_unit+"]",font_size=sp(15),bold=True,color=TEXT,
                size_hint_y=None,height=dp(24),halign='left'))
            # Error words
            words=unit_groups.get(self.error_unit,[])
            for e in words:
                r=repeat.get(e["kana"],1)
                d=e["kanji"]+"("+e["kana"]+")" if e["kanji"] else e["kana"]
                suffix=" x"+str(r) if r>1 else ""
                dv.add_widget(Label(text="  "+d+" -> "+e["cn"]+suffix,
                    font_size=sp(14),color=TEXT,size_hint_y=None,height=dp(26)))
            # Single-unit review button
            rev_row=BoxLayout(size_hint_y=None,height=dp(50))
            rev_row.add_widget(Widget())
            rev_btn=RoundedButton(text="复习本单元错题",bg=PRIMARY,size_hint=(None,None),width=dp(200))
            rev_btn.bind(on_release=lambda x:self._review_error_unit())
            rev_row.add_widget(rev_btn)
            rev_row.add_widget(Widget())
            dv.add_widget(rev_row)
            c.add_widget(dv)

        # Clear button
        cb=RoundedButton(text="[清] 清空全部错题",bg=(0.95,0.95,0.95,1),fc=TEXT)
        cb.bind(on_release=lambda x:self._clear_errors())
        c.add_widget(cb)

    def _error_dir_item(self,uname,cnt,cb):
        box=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(40),spacing=dp(12),padding=[0,dp(4)])
        box.add_widget(Label(text="["+uname+"]",font_size=sp(15),bold=True,color=PRIMARY,size_hint_x=1,halign='left'))
        cnt_lbl=Label(text=str(cnt)+"题",font_size=sp(13),color=TEXT_SECONDARY,size_hint=(None,1),width=dp(50))
        with cnt_lbl.canvas.before: Color(*PRIMARY_LIGHT); RoundedRectangle(pos=cnt_lbl.pos,size=cnt_lbl.size,radius=[10])
        cnt_lbl.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                     size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        box.add_widget(cnt_lbl)
        box.add_widget(Label(text=">",font_size=sp(18),color=(0.8,0.82,0.88,1),size_hint=(None,1),width=dp(20)))
        btn=Button(size_hint=(1,1),background_normal='',background_color=(0.3,0.56,0.85,0.08))
        btn.bind(on_release=lambda x:cb())
        box.add_widget(btn)
        return box

    def _open_error_unit(self,uname):
        self.error_unit=uname
        self.switch_tab(2)

    def _close_error_unit(self):
        self.error_unit=None
        self.switch_tab(2)

    def _review_error_unit(self):
        """复习单个单元的错题"""
        words=[e for e in self.app.errors if self._get_word_unit(e)==self.error_unit]
        uniq=[]; seen=set()
        for w in words:
            if w["kana"] not in seen: seen.add(w["kana"]); uniq.append(w)
        if not uniq: self.app.toast("本单元无错题"); return
        self.app.quiz_correct=0; self.app.quiz_streak=0; self.app.quiz_max_streak=0
        s=list(uniq); random.shuffle(s)
        cnt=min(10,len(s)); half=max(1,cnt//2)
        self.current_quiz_unit=self.error_unit
        self.app.quiz_cn_words=s[:half]; self.app.quiz_jp_words=s[half:cnt]
        self.app.quiz_total=len(self.app.quiz_cn_words)+len(self.app.quiz_jp_words)
        self.app.quiz_idx=0
        if self.app.quiz_cn_words: self.app.root.show_quiz('cn')
        elif self.app.quiz_jp_words: self.app.root.show_quiz('jp')

    def _jump_error_unit(self,uname):
        """结果页 → 跳转到指定单元的错题"""
        has_any=any(self._get_word_unit(e)==uname for e in self.app.errors)
        self.error_unit=uname if has_any else None
        self.switch_tab(2)

    def _clear_errors(self):
        if not self.app.errors: self.app.toast("已是空的"); return
        self.app.errors=[]; self.app._save(); self.error_unit=None; self.switch_tab(2)

    # ---------- 已掌握 ----------
    def _show_mastered(self):
        self._clear_content()
        scr=ScrollView(bar_width=dp(4))
        c=BoxLayout(orientation='vertical',size_hint_y=None,padding=[dp(16),dp(8),dp(16),dp(16)])
        c.bind(minimum_height=c.setter('height'))

        # Back button
        bk=RoundedButton(text="< 返回主页",bg=(0.95,0.95,0.95,1),fc=TEXT,size_hint=(None,None),width=dp(120),height=dp(36))
        bk.bind(on_release=lambda x:self.switch_tab(0))
        c.add_widget(bk)

        if not self.app.mastered:
            c.add_widget(Label(text="[!!] 还没有已掌握的单词",font_size=sp(16),color=TEXT_SECONDARY,size_hint_y=None,height=dp(60)))
        else:
            c.add_widget(Label(text="已掌握 "+str(len(self.app.mastered))+" 词",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(24)))
            cd=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
            cd.bind(minimum_height=cd.setter('height'))
            with cd.canvas.before: Color(*WHITE); RoundedRectangle(pos=cd.pos,size=cd.size,radius=[16])
            cd.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                    size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
            # Group mastered by unit (preserve order, dedup by kana)
            unit_groups={}
            seen=set()
            for w in self.app.mastered:
                if w["kana"] in seen: continue
                seen.add(w["kana"])
                unit=self._get_word_unit(w)
                if unit not in unit_groups: unit_groups[unit]=[]
                unit_groups[unit].append(w)
            for uname in sorted(unit_groups.keys()):
                cd.add_widget(Label(text="["+uname+"]",font_size=sp(13),bold=True,
                    color=TEXT_SECONDARY,size_hint_y=None,height=dp(22),halign='left'))
                for w in unit_groups[uname]:
                    d=w["kanji"]+"("+w["kana"]+")" if w["kanji"] else w["kana"]
                    cd.add_widget(Label(text="  [V] "+d+" -> "+w["cn"],
                        font_size=sp(14),color=TEXT,size_hint_y=None,height=dp(26)))
            cd.bind(minimum_height=cd.setter('height'))
            c.add_widget(cd)
        scr.add_widget(c)
        self.content.add_widget(scr)

    # ---------- 答题 ----------
    def show_quiz(self,mode):
        self._clear_content()
        self.quiz_mode=mode
        if mode=='cn': self._build_quiz_cn()
        else: self._build_quiz_jp()

    def _check_cn(self,w,a_kanji,a_kana):
        has=bool(w["kanji"])
        return (a_kanji==w["kanji"] and a_kana==w["kana"]) if has else (a_kana==w["kana"])

    def _check_jp(self,w,ans):
        return ans in [m.strip() for m in w["cn"].split("、")]

    def _submit_quiz(self,correct_ans,detail_text):
        self.submit_btn.opacity=0; self.submit_btn.disabled=True
        self.fb_box.opacity=1; self.fb_box.disabled=False
        self.fb_icon.text="[OK]" if correct_ans else "[XX]"
        self.fb_text.text="正确！[!!]" if correct_ans else "错误"
        self.fb_detail.text=detail_text
        with self.fb_box.canvas.before:
            self.fb_box.canvas.before.clear()
            Color(*SUCCESS) if correct_ans else Color(*DANGER)
            RoundedRectangle(pos=self.fb_box.pos,size=self.fb_box.size,radius=[12])
        self.fb_box.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v) if s.canvas.before.children else None,
                          size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v) if s.canvas.before.children else None)

        is_last=self.app.quiz_idx>=self.quiz_len-1
        has_next=self.quiz_mode=='cn' and self.app.quiz_jp_words
        if is_last and not has_next: self.next_btn.text="查看结果"
        elif is_last: self.next_btn.text="进入日译中"
        else: self.next_btn.text="下一题 >"
        self.next_btn.opacity=1; self.next_btn.disabled=False

    def _next_quiz(self):
        self.app.quiz_idx+=1
        self.next_btn.opacity=0; self.next_btn.disabled=True
        self.fb_box.opacity=0; self.fb_box.disabled=True
        self.submit_btn.opacity=1; self.submit_btn.disabled=False

        if self.quiz_mode=='cn':
            if self.app.quiz_idx<len(self.app.quiz_cn_words):
                self._show_cn_q()
            elif self.app.quiz_jp_words:
                self.quiz_mode='jp'; self.app.quiz_idx=0
                self._clear_content()
                self._build_quiz_jp()
            else:
                self._show_result_view()
        else:
            if self.app.quiz_idx<len(self.app.quiz_jp_words):
                self._show_jp_q()
            else:
                self._show_result_view()

    def _show_result_view(self):
        self.app.show_result()

    def _build_quiz_cn(self):
        self.quiz_len=len(self.app.quiz_cn_words)
        self.app.quiz_idx=0
        root=BoxLayout(orientation='vertical')
        self.q_header=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(48),padding=[dp(12),0])
        with self.q_header.canvas.before: Color(*WHITE); Rectangle(pos=self.q_header.pos,size=self.q_header.size)
        self.q_header.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                           size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        bk=Button(text="<",font_size=sp(20),size_hint=(None,1),width=dp(36),
                   background_normal='',background_color=(0,0,0,0),color=TEXT)
        bk.bind(on_release=lambda x:self.switch_tab(0))
        self.q_header.add_widget(bk)
        self.q_header.add_widget(Label(text="[题] 中译日",font_size=sp(17),bold=True,color=TEXT))
        root.add_widget(self.q_header)

        self.q_prog=Label(text="",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(24))
        root.add_widget(self.q_prog)

        # Question card
        qc=BoxLayout(orientation='vertical',size_hint_y=None,padding=[dp(40),dp(20)],spacing=dp(8))
        qc.bind(minimum_height=qc.setter('height'))
        with qc.canvas.before: Color(*PRIMARY); RoundedRectangle(pos=qc.pos,size=qc.size,radius=[16])
        qc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        qc.add_widget(Label(text="请翻译成日语",font_size=sp(14),color=(1,1,1,0.8),size_hint_y=None,height=dp(22)))
        self.q_text=Label(text="",font_size=sp(32),bold=True,color=WHITE,size_hint_y=None,height=dp(60))
        qc.add_widget(self.q_text)
        root.add_widget(qc)

        # Inputs
        ia=BoxLayout(orientation='vertical',padding=[dp(16),dp(16),dp(16),0],spacing=dp(12))
        for idx,(label,hint,wid) in enumerate([("[题] 日语汉字","例：食べる","kanji"),("[声] 日语假名","例：たべる","kana")]):
            b=BoxLayout(orientation='vertical',size_hint_y=None,height=dp(60),spacing=dp(4))
            b.add_widget(Label(text=label,font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(18)))
            ti=TextInput(hint_text=hint,font_size=sp(18),size_hint_y=None,height=dp(36),
                         background_color=WHITE,foreground_color=TEXT,padding=[dp(8),dp(4)],
                         multiline=False,focus=False)
            setattr(self,'in_'+wid,ti); b.add_widget(ti); ia.add_widget(b)
            if idx==0:
                Clock.schedule_once(lambda dt,t=ti: setattr(t,'focus',True), 0.3)

        self.submit_btn=RoundedButton(text="提交答案",bg=PRIMARY)
        self.submit_btn.bind(on_release=lambda x:self._on_submit_cn())
        ia.add_widget(self.submit_btn)

        # Feedback
        self.fb_box=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
        self.fb_box.bind(minimum_height=self.fb_box.setter('height'))
        with self.fb_box.canvas.before: Color(*SUCCESS); RoundedRectangle(pos=self.fb_box.pos,size=self.fb_box.size,radius=[12])
        self.fb_box.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v) if s.canvas.before.children else None,
                          size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v) if s.canvas.before.children else None)
        self.fb_icon=Label(text="[OK]",font_size=sp(28),size_hint_y=None,height=dp(32))
        self.fb_text=Label(text="正确",font_size=sp(15),color=TEXT,size_hint_y=None,height=dp(22))
        self.fb_detail=Label(text="",font_size=sp(13),color=TEXT_SECONDARY,size_hint_y=None,height=dp(18))
        self.fb_box.add_widget(self.fb_icon); self.fb_box.add_widget(self.fb_text); self.fb_box.add_widget(self.fb_detail)
        self.next_btn=RoundedButton(text="下一题 >",bg=PRIMARY)
        self.next_btn.bind(on_release=lambda x:self._next_quiz())
        self.fb_box.add_widget(self.next_btn)
        self.fb_box.opacity=0; self.fb_box.disabled=True
        self.next_btn.opacity=0; self.next_btn.disabled=True
        ia.add_widget(self.fb_box)
        root.add_widget(ia)
        self.content.add_widget(root)
        Clock.schedule_once(lambda dt: self._show_cn_q(), 0.1)

    def _show_cn_q(self):
        if self.app.quiz_idx>=len(self.app.quiz_cn_words): return
        w=self.app.quiz_cn_words[self.app.quiz_idx]
        meanings=w["cn"].split("、")
        self.q_text.text=random.choice(meanings)
        self.q_prog.text="第 "+str(self.app.quiz_idx+1)+"/"+str(self.quiz_len)+" 题"
        self.in_kanji.text=""; self.in_kana.text=""

    def _on_submit_cn(self):
        if self.app.quiz_idx>=len(self.app.quiz_cn_words): return
        w=self.app.quiz_cn_words[self.app.quiz_idx]
        correct=self._check_cn(w,self.in_kanji.text.strip(),self.in_kana.text.strip())
        has=bool(w["kanji"])
        detail=(w["kanji"]+"("+w["kana"]+")" if has else w["kana"])+" -> "+w["cn"]
        if correct:
            self.app.quiz_correct+=1; self.app.quiz_streak+=1
            if self.app.quiz_streak>self.app.quiz_max_streak: self.app.quiz_max_streak=self.app.quiz_streak
            if not any(m["kana"]==w["kana"] for m in self.app.mastered): self.app.mastered.append(w)
            self.app.errors=[e for e in self.app.errors if e["kana"]!=w["kana"]]
        else:
            self.app.quiz_streak=0
            if not any(e["kana"]==w["kana"] for e in self.app.errors): self.app.errors.append(w)
        self.app._save()
        self._submit_quiz(correct,detail)

    def _build_quiz_jp(self):
        self.quiz_len=len(self.app.quiz_jp_words)
        self.app.quiz_idx=0
        root=BoxLayout(orientation='vertical')
        h=BoxLayout(orientation='horizontal',size_hint_y=None,height=dp(48),padding=[dp(12),0])
        with h.canvas.before: Color(*WHITE); Rectangle(pos=h.pos,size=h.size)
        h.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
               size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        bk=Button(text="<",font_size=sp(20),size_hint=(None,1),width=dp(36),
                   background_normal='',background_color=(0,0,0,0),color=TEXT)
        bk.bind(on_release=lambda x:self.switch_tab(0))
        h.add_widget(bk)
        h.add_widget(Label(text="[题] 日译中",font_size=sp(17),bold=True,color=TEXT))
        root.add_widget(h)

        self.q_prog=Label(text="",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(24))
        root.add_widget(self.q_prog)

        qc=BoxLayout(orientation='vertical',size_hint_y=None,padding=[dp(40),dp(20)],spacing=dp(4))
        qc.bind(minimum_height=qc.setter('height'))
        with qc.canvas.before: Color(*WARNING); RoundedRectangle(pos=qc.pos,size=qc.size,radius=[16])
        qc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        qc.add_widget(Label(text="这是什么意思？",font_size=sp(14),color=(1,1,1,0.8),size_hint_y=None,height=dp(22)))
        self.jp_kana=Label(text="",font_size=sp(15),color=(1,1,1,0.7),size_hint_y=None,height=dp(24))
        qc.add_widget(self.jp_kana)
        self.jp_kanji=Label(text="",font_size=sp(32),bold=True,color=WHITE,size_hint_y=None,height=dp(48))
        qc.add_widget(self.jp_kanji)
        root.add_widget(qc)

        ia=BoxLayout(orientation='vertical',padding=[dp(16),dp(16),dp(16),0],spacing=dp(12))
        b=BoxLayout(orientation='vertical',size_hint_y=None,height=dp(60),spacing=dp(4))
        b.add_widget(Label(text="[中] 中文意思",font_size=sp(14),color=TEXT_SECONDARY,size_hint_y=None,height=dp(18)))
        self.in_ans=TextInput(hint_text="输入中文翻译",font_size=sp(18),size_hint_y=None,height=dp(36),
                               background_color=WHITE,foreground_color=TEXT,padding=[dp(8),dp(4)],
                               multiline=False,focus=False)
        b.add_widget(self.in_ans); ia.add_widget(b)
        Clock.schedule_once(lambda dt: setattr(self.in_ans,'focus',True), 0.3)

        self.submit_btn=RoundedButton(text="提交答案",bg=PRIMARY)
        self.submit_btn.bind(on_release=lambda x:self._on_submit_jp())
        ia.add_widget(self.submit_btn)

        self.fb_box=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(16),spacing=dp(4))
        self.fb_box.bind(minimum_height=self.fb_box.setter('height'))
        with self.fb_box.canvas.before: Color(*SUCCESS); RoundedRectangle(pos=self.fb_box.pos,size=self.fb_box.size,radius=[12])
        self.fb_box.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v) if s.canvas.before.children else None,
                          size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v) if s.canvas.before.children else None)
        self.fb_icon=Label(text="[OK]",font_size=sp(28),size_hint_y=None,height=dp(32))
        self.fb_text=Label(text="正确",font_size=sp(15),color=TEXT,size_hint_y=None,height=dp(22))
        self.fb_detail=Label(text="",font_size=sp(13),color=TEXT_SECONDARY,size_hint_y=None,height=dp(18))
        self.fb_box.add_widget(self.fb_icon); self.fb_box.add_widget(self.fb_text); self.fb_box.add_widget(self.fb_detail)
        self.next_btn=RoundedButton(text="下一题 >",bg=PRIMARY)
        self.next_btn.bind(on_release=lambda x:self._next_quiz())
        self.fb_box.add_widget(self.next_btn)
        self.fb_box.opacity=0; self.fb_box.disabled=True
        self.next_btn.opacity=0; self.next_btn.disabled=True
        ia.add_widget(self.fb_box)
        root.add_widget(ia)
        self.content.add_widget(root)
        Clock.schedule_once(lambda dt: self._show_jp_q(), 0.1)

    def _show_jp_q(self):
        if self.app.quiz_idx>=len(self.app.quiz_jp_words): return
        w=self.app.quiz_jp_words[self.app.quiz_idx]
        self.q_prog.text="第 "+str(self.app.quiz_idx+1)+"/"+str(self.quiz_len)+" 题"
        if w["kanji"]:
            self.jp_kana.text=w["kana"]; self.jp_kana.font_size=sp(15)
            self.jp_kanji.text=w["kanji"]; self.jp_kanji.font_size=sp(32)
        else:
            self.jp_kana.text=w["kana"]; self.jp_kana.font_size=sp(32)
            self.jp_kanji.text=""
        self.in_ans.text=""

    def _on_submit_jp(self):
        if self.app.quiz_idx>=len(self.app.quiz_jp_words): return
        w=self.app.quiz_jp_words[self.app.quiz_idx]
        correct=self._check_jp(w,self.in_ans.text.strip())
        if correct:
            self.app.quiz_correct+=1; self.app.quiz_streak+=1
            if self.app.quiz_streak>self.app.quiz_max_streak: self.app.quiz_max_streak=self.app.quiz_streak
            if not any(m["kana"]==w["kana"] for m in self.app.mastered): self.app.mastered.append(w)
            self.app.errors=[e for e in self.app.errors if e["kana"]!=w["kana"]]
        else:
            self.app.quiz_streak=0
            if not any(e["kana"]==w["kana"] for e in self.app.errors): self.app.errors.append(w)
        self.app._save()
        self._submit_quiz(correct,w["cn"])

    # ---------- 结果 ----------
    def show_result(self):
        self._clear_content()
        root=BoxLayout(orientation='vertical',size_hint_y=None,padding=[dp(16),dp(16),dp(16),dp(16)],spacing=dp(16))
        total=self.app.quiz_total; corr=self.app.quiz_correct
        pct=round(corr/total*100) if total>0 else 0

        sc=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(24),spacing=dp(8))
        sc.bind(minimum_height=sc.setter('height'))
        with sc.canvas.before: Color(*WHITE); RoundedRectangle(pos=sc.pos,size=sc.size,radius=[16])
        sc.bind(pos=lambda s,v:setattr(s.canvas.before.children[-1],'pos',v),
                size=lambda s,v:setattr(s.canvas.before.children[-1],'size',v))
        emoji="[冠]" if pct>=90 else "[棒]" if pct>=70 else "[练]" if pct>=50 else "[学]"
        title="太棒了！" if pct>=90 else "表现不错！" if pct>=70 else "还需加油" if pct>=50 else "需要更多练习"
        sc.add_widget(Label(text=emoji,font_size=sp(48),size_hint_y=None,height=dp(60)))
        sc.add_widget(Label(text=title,font_size=sp(20),bold=True,color=TEXT,size_hint_y=None,height=dp(28)))
        sc.add_widget(Label(text=str(pct)+"%",font_size=sp(32),bold=True,color=SUCCESS,size_hint_y=None,height=dp(40)))
        root.add_widget(sc)

        st=BoxLayout(size_hint_y=None,height=dp(80),spacing=dp(12))
        for label,val in [("[OK]答对",corr),("[题]总题",total),("[连]连对",self.app.quiz_max_streak)]:
            s=BoxLayout(orientation='vertical',size_hint_y=None,padding=dp(8))
            s.bind(minimum_height=s.setter('height'))
            with s.canvas.before: Color(*WHITE); RoundedRectangle(pos=s.pos,size=s.size,radius=[12])
            s.bind(pos=lambda q,v:setattr(q.canvas.before.children[-1],'pos',v),
                    size=lambda q,v:setattr(q.canvas.before.children[-1],'size',v))
            s.add_widget(Label(text=str(val),font_size=sp(28),bold=True,color=PRIMARY,size_hint_y=None,height=dp(36)))
            s.add_widget(Label(text=label,font_size=sp(13),color=TEXT_SECONDARY,size_hint_y=None,height=dp(20)))
            st.add_widget(s)
        root.add_widget(st)

        root.add_widget(RoundedButton(text="返回主页",bg=PRIMARY,on_release=lambda x:self.switch_tab(0)))
        # 会话刷题：下一轮 or 更换单元
        if self.app.quiz_active:
            remain=len(self.app.quiz_all_words)-self.app.quiz_start_index
            if remain>0:
                root.add_widget(RoundedButton(text="进行下一轮答题 ("+str(remain)+"词待测)",
                    bg=SUCCESS,fc=WHITE,on_release=lambda x:self.app._next_round()))
            else:
                self.app.quiz_active=False
                root.add_widget(RoundedButton(text="更换单元",
                    bg=PRIMARY,on_release=lambda x:self.switch_tab(1)))
        err_unit=self.current_quiz_unit
        root.add_widget(RoundedButton(text="查看错题",bg=(0.95,0.95,0.95,1),fc=TEXT,
            on_release=lambda x,eu=err_unit:self._jump_error_unit(eu)))
        scr=ScrollView()
        root.bind(minimum_height=root.setter('height'))
        c=BoxLayout(orientation='vertical',size_hint_y=None); c.bind(minimum_height=c.setter('height'))
        c.add_widget(root); scr.add_widget(c)
        self.content.add_widget(scr)


# ==================== 启动 ====================
if __name__=="__main__":
    JpApp().run()
